import json, statistics
files = ['alg_deep.json','geo_deep.json']
correct=[]; incorrect=[]
for f in files:
    qs = json.load(open(f))['questions']
    for q in qs:
        for s in q['samples']:
            if s['correct']: correct.append(s['score'])
            else: incorrect.append(s['score'])
print('alg/geo deep: correct mean', statistics.mean(correct), 'n', len(correct))
print('alg/geo deep: incorrect mean', statistics.mean(incorrect), 'n', len(incorrect))

